import random
import string
from typing import List

# Target: Generate valid SQL-like subscription expressions for DDS MultiTopic
# The fuzzer stub constructs:
# - name: arbitrary non-empty string (<=255)
# - type: arbitrary non-empty string (<=255)
# - expr: FUZZ_PARAM_STR() (<=512) -> SQL-like subscription expression
# Our generator should therefore primarily return a bytes buffer intended to be
# consumed by FUZZ_PARAM_STR for the subscription expression. Many fuzz harnesses
# will reuse the same initial buffer for multiple FUZZ_PARAM_STR calls; to make
# it useful, we include multiple newline-separated candidates so the fuzzer can
# slice or select from them. Each line is a plausible, valid SQL-like filter.

_IDENT_START = string.ascii_letters + "_"
_IDENT_CHARS = string.ascii_letters + string.digits + "_"

def _ident(rng: random.Random, min_len=1, max_len=12) -> str:
    n = rng.randint(min_len, max_len)
    s = rng.choice(_IDENT_START)
    if n > 1:
        s += ''.join(rng.choice(_IDENT_CHARS) for _ in range(n-1))
    return s

def _string_lit(rng: random.Random, min_len=0, max_len=20) -> str:
    # DDS SQL uses single quotes for string literals; escape single quotes by doubling
    n = rng.randint(min_len, max_len)
    chars = string.ascii_letters + string.digits + " _-:/.,@#"
    raw = ''.join(rng.choice(chars) for _ in range(n))
    esc = raw.replace("'", "''")
    return f"'{esc}'"

def _number(rng: random.Random) -> str:
    # Mix integers and floats, including signs
    if rng.random() < 0.5:
        val = rng.randint(-2**15, 2**15-1)
        return str(val)
    else:
        val = (rng.random() * 2000.0) - 1000.0
        # Limit precision
        return f"{val:.{rng.randint(0,6)}f}"

def _bool(rng: random.Random) -> str:
    return rng.choice(["TRUE", "FALSE"])

def _comparison_op(rng: random.Random) -> str:
    return rng.choice(["=", "!=", "<", "<=", ">", ">="])

def _logical_op(rng: random.Random) -> str:
    return rng.choice(["AND", "OR"])

def _like_pattern(rng: random.Random) -> str:
    # Use % and _ wildcards
    parts = []
    alphabet = string.ascii_letters + string.digits
    for _ in range(rng.randint(1, 4)):
        if rng.random() < 0.6:
            parts.append('%')
        elif rng.random() < 0.5:
            parts.append('_')
        else:
            parts.append(''.join(rng.choice(alphabet) for _ in range(rng.randint(1, 3))))
    s = ''.join(parts)
    return f"'{s}'"

def _field_access(rng: random.Random) -> str:
    # Possibly nested field: a, a.b, a.b.c
    depth = 1 if rng.random() < 0.6 else rng.randint(2, 3)
    return '.'.join(_ident(rng) for _ in range(depth))

def _param_ref(rng: random.Random) -> str:
    # Parameters are referenced as %n in DDS SQL-like filters
    return '%' + str(rng.randint(0, 9))

def _in_list(rng: random.Random) -> str:
    # Generate IN list with mixture of strings and numbers
    items: List[str] = []
    k = rng.randint(1, 6)
    for _ in range(k):
        items.append(rng.choice([_string_lit(rng), _number(rng)]))
    return '(' + ', '.join(items) + ')'

def _single_predicate(rng: random.Random) -> str:
    fld = _field_access(rng)
    kind = rng.random()
    if kind < 0.25:
        return f"{fld} {_comparison_op(rng)} {_number(rng)}"
    elif kind < 0.5:
        return f"{fld} {_comparison_op(rng)} {_string_lit(rng)}"
    elif kind < 0.7:
        return f"{fld} LIKE {_like_pattern(rng)}"
    elif kind < 0.85:
        return f"{fld} IN {_in_list(rng)}"
    else:
        # Parameterized predicate
        return f"{fld} {_comparison_op(rng)} {_param_ref(rng)}"

def _between_predicate(rng: random.Random) -> str:
    fld = _field_access(rng)
    if rng.random() < 0.5:
        lo, hi = sorted([rng.randint(0, 1000), rng.randint(0, 1000)])
        return f"{fld} BETWEEN {lo} AND {hi}"
    else:
        a = _string_lit(rng)
        b = _string_lit(rng)
        # String order is lexical; still valid
        return f"{fld} BETWEEN {a} AND {b}"

def _is_null_predicate(rng: random.Random) -> str:
    fld = _field_access(rng)
    return f"{fld} IS " + rng.choice(["NULL", "NOT NULL"])

def _paren(expr: str) -> str:
    return f"({expr})"

def _where_clause(rng: random.Random) -> str:
    # Construct a balanced boolean expression combining predicates
    parts: List[str] = []
    count = rng.randint(1, 5)
    for i in range(count):
        pred_choice = rng.random()
        if pred_choice < 0.6:
            pred = _single_predicate(rng)
        elif pred_choice < 0.8:
            pred = _between_predicate(rng)
        else:
            pred = _is_null_predicate(rng)
        if rng.random() < 0.4:
            pred = _paren(pred)
        parts.append(pred)
    # Combine with AND/OR, optionally with NOT
    expr = parts[0]
    for p in parts[1:]:
        op = _logical_op(rng)
        rhs = p
        if rng.random() < 0.25:
            rhs = "NOT " + _paren(rhs)
        if rng.random() < 0.3:
            expr = _paren(expr)
        expr = f"{expr} {op} {rhs}"
    # Optionally prepend NOT on the whole
    if rng.random() < 0.15 and len(parts) > 1:
        expr = "NOT " + _paren(expr)
    return expr

def _select_clause(rng: random.Random) -> str:
    # DDS MultiTopic supports SELECT field lists, possibly with aliases
    sel_items: List[str] = []
    n = rng.randint(1, 6)
    for _ in range(n):
        if rng.random() < 0.2:
            sel = '*'
        else:
            sel = _field_access(rng)
            if rng.random() < 0.25:
                sel += f" AS {_ident(rng)}"
        sel_items.append(sel)
    return 'SELECT ' + ', '.join(sel_items)

def _from_clause(rng: random.Random) -> str:
    # One or multiple topic names with optional aliases
    topics: List[str] = []
    k = 1 if rng.random() < 0.6 else rng.randint(2, 4)
    for _ in range(k):
        t = _ident(rng)
        if rng.random() < 0.5:
            t += f" AS {_ident(rng)}"
        topics.append(t)
    return 'FROM ' + ', '.join(topics)

def _build_expression(rng: random.Random) -> str:
    # Build either a pure WHERE filter (commonly used) or full SELECT ... FROM ... WHERE ...
    style = rng.random()
    if style < 0.5:
        # WHERE-only filters are accepted by some DDS APIs for ContentFilteredTopic/MultiTopic filter expressions
        return _where_clause(rng)
    else:
        q = _select_clause(rng) + ' ' + _from_clause(rng)
        if rng.random() < 0.9:
            q += ' WHERE ' + _where_clause(rng)
        return q

def _dedup_keep_order(items: List[str]) -> List[str]:
    seen = set()
    out = []
    for s in items:
        if s not in seen:
            seen.add(s)
            out.append(s)
    return out

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Include a mix of canonical and parameterized expressions
    exprs: List[str] = []

    # Deterministic baseline cases
    exprs.append("TRUE")
    exprs.append("FALSE")
    exprs.append("x = 1")
    exprs.append("x != 0 AND y >= -5")
    exprs.append("name LIKE '%foo%' OR id IN (1, 2, 3)")
    exprs.append("NOT (temperature BETWEEN -10 AND 50)")
    exprs.append("status IS NOT NULL")
    exprs.append("key = %0 AND region = %1")

    # Randomly generated rich cases
    for _ in range(rng.randint(8, 16)):
        exprs.append(_build_expression(rng))

    # Ensure total size <= 4096; join with newlines so the harness can split/select
    exprs = _dedup_keep_order(exprs)
    blob = "\n".join(exprs)
    if len(blob) > 4096:
        # Trim from the end while maintaining validity
        while len(blob) > 4096 and exprs:
            exprs.pop()
            blob = "\n".join(exprs)
    return blob.encode('utf-8')

import random
import string
from typing import List

# This generator produces valid C++ std::regex patterns (ECMAScript default)
# to be consumed by FUZZ_PARAM_STR in the fuzzing stubs of:
# - Log::SetCategoryFilter
# - Log::SetFilenameFilter
# - Log::SetErrorStringFilter
#
# We focus on generating syntactically valid and diverse regex patterns
# (anchors, groups, alternations, character classes, quantifiers, lookarounds
# avoided as they are unsupported in ECMAScript), and include common filename
# oriented constructs for the filename filter use-case.

META_CHARS_SIMPLE = [".", "^", "$", "|", "?", "+", "*"]
# Quantifiers that require valid preceding atom; we ensure placement carefully.
QUANTIFIERS = ["*", "+", "?", "{1}", "{2}", "{0,1}", "{1,3}", "{0,}", "{2,}"]

# Safe character class atoms for ECMAScript
CLASS_ATOMS = list(string.ascii_letters + string.digits + " _-.:@")

LITERAL_CHARS = list(string.ascii_letters + string.digits + " _-.:@")

FILE_EXTS = ["log", "txt", "xml", "json", "ini", "cfg", "yaml", "cpp", "hpp"]
FILE_DIRS = ["/var/log/", "/tmp/", "C:/Windows/", "C:/Temp/", "./", "../"]
CATEGORIES = ["DDS", "RTPS", "NETWORK", "TRANSPORT", "DISCOVERY", "SECURITY", "XML", "QoS"]

def rand_choice(rng: random.Random, seq: List[str]) -> str:
    return seq[rng.randrange(len(seq))]

def rand_literal(rng: random.Random, min_len: int = 1, max_len: int = 10) -> str:
    n = rng.randint(min_len, max_len)
    return ''.join(rng.choice(LITERAL_CHARS) for _ in range(n))

def make_char_class(rng: random.Random) -> str:
    # Build a valid non-empty character class, escaping ']' and '-' positions appropriately
    size = rng.randint(1, 6)
    elems = []
    # Optionally add ranges like a-z, A-Z, 0-9
    if rng.random() < 0.5:
        ranges = []
        if rng.random() < 0.8:
            ranges.append("a-z")
        if rng.random() < 0.6:
            ranges.append("A-Z")
        if rng.random() < 0.7:
            ranges.append("0-9")
        if ranges:
            elems.append(''.join(rng.sample(ranges, k=len(ranges))))
    while len(elems) < size:
        ch = rng.choice(CLASS_ATOMS)
        if ch == ']':
            ch = '\\]'
        if ch == '-':
            ch = '\\-'
        elems.append(ch)
    # Avoid empty or invalid class like [] or [^]
    neg = '^' if rng.random() < 0.3 else ''
    content = ''.join(elems)
    return f"[{neg}{content}]"

def maybe_quantify(rng: random.Random, atom: str) -> str:
    if rng.random() < 0.6:
        q = rand_choice(rng, QUANTIFIERS)
        return atom + q
    return atom

def make_group(rng: random.Random, inner: str) -> str:
    # Non-capturing groups are not in ECMAScript; use capturing only
    return f"({inner})"

def make_alternation(rng: random.Random, parts: List[str]) -> str:
    # Ensure no empty alternatives
    parts = [p for p in parts if p]
    if len(parts) < 2:
        return parts[0] if parts else ""
    return "|".join(parts)

def escape_literal_for_regex(s: str) -> str:
    # Escape characters that have meaning in regex
    esc = ""
    for ch in s:
        if ch in ".^$|?*+()[]{}\\":
            esc += "\\" + ch
        else:
            esc += ch
    return esc

def filename_pattern(rng: random.Random) -> str:
    # Construct patterns that resemble paths or filenames
    prefix = rand_choice(rng, FILE_DIRS) if rng.random() < 0.6 else ""
    name = rand_literal(rng, 1, 8)
    if rng.random() < 0.5:
        # Insert a class for name variability
        name += make_char_class(rng) + maybe_quantify(rng, "")
    ext = "." + rand_choice(rng, FILE_EXTS) if rng.random() < 0.9 else ""
    pat_core = escape_literal_for_regex(prefix) + name + escape_literal_for_regex(ext)
    # Optionally anchor
    if rng.random() < 0.5:
        pat_core = "^" + pat_core
    if rng.random() < 0.5:
        pat_core = pat_core + "$"
    return pat_core

def category_pattern(rng: random.Random) -> str:
    # Alternation of known categories with optional prefixes/suffixes
    parts = []
    k = rng.randint(2, min(5, len(CATEGORIES)))
    for cat in rng.sample(CATEGORIES, k=k):
        piece = escape_literal_for_regex(cat)
        if rng.random() < 0.5:
            piece = make_group(rng, piece)
        if rng.random() < 0.4:
            piece = piece + maybe_quantify(rng, "")
        parts.append(piece)
    alt = make_alternation(rng, parts)
    # Add optional word boundaries (ECMAScript supports \b)
    if rng.random() < 0.6:
        alt = "\\b(" + alt + ")\\b"
    # Optional anchors
    if rng.random() < 0.4:
        alt = "^" + alt
    if rng.random() < 0.4:
        alt = alt + "$"
    return alt

def generic_pattern(rng: random.Random) -> str:
    # Build a general-purpose regex with literals, classes, groups, alternation, and quantifiers
    seq = []
    length = rng.randint(2, 6)
    for _ in range(length):
        choice = rng.random()
        if choice < 0.25:
            atom = escape_literal_for_regex(rand_literal(rng, 1, 5))
        elif choice < 0.5:
            atom = make_char_class(rng)
        elif choice < 0.7:
            # dot atom
            atom = "."
        else:
            # small grouped literal or class
            inner = escape_literal_for_regex(rand_literal(rng, 1, 3))
            if rng.random() < 0.5:
                inner += make_char_class(rng)
            atom = make_group(rng, inner)
        atom = maybe_quantify(rng, atom)
        seq.append(atom)
    core = ''.join(seq)
    # Insert alternation between chunks
    if rng.random() < 0.5:
        chunk2 = ''.join(maybe_quantify(rng, make_char_class(rng)) for _ in range(rng.randint(1, 3)))
        core = make_group(rng, core) + "|" + make_group(rng, chunk2)
    # Optional anchors
    if rng.random() < 0.5:
        core = ("^" if rng.random() < 0.5 else "") + core + ("$" if rng.random() < 0.5 else "")
    return core

def ensure_valid(pattern: str) -> str:
    # Basic sanity tweaks to avoid empty or purely quantifier patterns
    if not pattern:
        return "^.*$"
    # Avoid patterns ending with stray backslash
    if pattern.endswith("\\"):
        pattern += "\\\\"
    return pattern

def build_pattern(rng: random.Random) -> str:
    mode = rng.random()
    if mode < 0.33:
        pat = filename_pattern(rng)
    elif mode < 0.66:
        pat = category_pattern(rng)
    else:
        pat = generic_pattern(rng)
    return ensure_valid(pat)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Produce between 1 and 3 concatenated patterns separated by newlines to give the fuzzer choices
    # FUZZ_PARAM_STR reads a single string; multiple patterns separated by newlines are each valid
    # regex strings individually when picked by the fuzzer harness that may slice inputs.
    count = rng.randint(1, 3)
    patterns = [build_pattern(rng) for _ in range(count)]
    data = "\n".join(patterns)
    # Limit to 4096 bytes
    b = data.encode('utf-8')[:4096]
    return b
